import os
import sys
import json
import base64
import re
import subprocess
import webbrowser
from pathlib import Path

def safe_b64decode(b64_str):
    clean = re.sub(r'[^A-Za-z0-9+/=]', '', b64_str)
    missing = len(clean) % 4
    if missing:
        clean += '=' * (4 - missing)
    return base64.b64decode(clean)

def extract_web_files(target_dir):
    print("📦 Preparando archivos de la Aplicación Web DC Control...")
    blobs = {}
    blobs["backend/main.py"] = ""
    
    for relative_path, b64_data in blobs.items():
        dest_path = os.path.join(target_dir, relative_path)
        os.makedirs(os.path.dirname(dest_path), exist_ok=True)
        content_bytes = safe_b64decode(b64_data)
        with open(dest_path, "wb") as f:
            f.write(content_bytes)
    print("✔️ Archivos web preparados correctamente.")

def run_web_server():
    base_dir = os.path.dirname(os.path.abspath(__file__))
    target_dir = os.path.join(base_dir, "DC_Control_Web_App")
    
    extract_web_files(target_dir)

    os.chdir(target_dir)
    sys.path.insert(0, os.path.join(target_dir, "backend"))

    print("\n=====================================================================")
    print("       🚀 SERVIDOR WEB DC CONTROL INICIADO CON ÉXITO                ")
    print("=====================================================================")
    
    port = int(os.environ.get("PORT", 8000))

    try:
        import uvicorn
    except ImportError:
        print("Instalando dependencias de servidor web...")
        subprocess.run([sys.executable, "-m", "pip", "install", "fastapi", "uvicorn", "psycopg2-binary", "pydantic", "python-multipart", "matplotlib", "pandas", "numpy"], check=True)
        import uvicorn

    import main
    uvicorn.run(main.app, host="0.0.0.0", port=port, log_level="info")

if __name__ == "__main__":
    run_web_server()
